begin;
create function pg_temp.check(value boolean,label text) returns void language plpgsql as $$begin if not coalesce(value,false) then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.denied(statement text) returns boolean language plpgsql as $$begin execute statement;return false;exception when insufficient_privilege then return true;end$$;
select pg_temp.check(not has_function_privilege('authenticated','cx_acquire_billing_sync(uuid,uuid)','EXECUTE'),'lease internal only');
select pg_temp.check(not has_function_privilege('anon','duplicate_menu(uuid)','EXECUTE'),'anonymous RPC revoked');
set local role authenticated;
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select pg_temp.check((select count(*)=1 from menus),'active owner reads only own menus');
insert into menus(id,business_id,name,slug) values('99999999-9999-4999-8999-999999999999','11111111-1111-4111-8111-111111111111','Delete with language settings','delete-with-settings');
select pg_temp.check((select count(*)=1 from menu_language_settings where menu_id='99999999-9999-4999-8999-999999999999'),'menu language settings initialized');
delete from menus where id='99999999-9999-4999-8999-999999999999';
select pg_temp.check((select count(*)=0 from menu_language_settings where menu_id='99999999-9999-4999-8999-999999999999'),'authorized parent DELETE cascades safely');
select pg_temp.check(pg_temp.denied($q$delete from businesses where id='11111111-1111-4111-8111-111111111111'$q$),'direct business deletion cannot orphan billing');
insert into products(business_id,name,price) values('11111111-1111-4111-8111-111111111111','Allowed',1);
select pg_temp.check(pg_temp.denied($q$insert into products(business_id,name,price) values('22222222-2222-4222-8222-222222222222','Foreign',1)$q$),'foreign write rejected');
select pg_temp.check(pg_temp.denied($q$update menus set id='99999999-9999-4999-8999-999999999999' where id='33333333-3333-4333-8333-333333333333'$q$),'resource identity is immutable');
select pg_temp.check(pg_temp.denied($q$update menus set business_id='22222222-2222-4222-8222-222222222222' where id='33333333-3333-4333-8333-333333333333'$q$),'reassignment rejected');
insert into storage.objects(bucket_id,name) values('product-images','11111111-1111-4111-8111-111111111111/77777777-7777-4777-8777-777777777777/file.webp');
select pg_temp.check(pg_temp.denied($q$insert into storage.objects(bucket_id,name) values('product-images','22222222-2222-4222-8222-222222222222/00000000-0000-4000-8000-000000000000/file.webp')$q$),'foreign product storage denied');
reset role;
update subscriptions set status='past_due' where business_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select pg_temp.check((select count(*)=0 from menus),'past_due has no premium reads');
select pg_temp.check(pg_temp.denied($q$insert into products(business_id,name,price) values('11111111-1111-4111-8111-111111111111','No access',1)$q$),'past_due cannot create');
select pg_temp.check(pg_temp.denied($q$select duplicate_menu('33333333-3333-4333-8333-333333333333')$q$),'SECURITY DEFINER duplication cannot bypass');
select pg_temp.check(pg_temp.denied($q$insert into storage.objects(bucket_id,name) values('product-images','11111111-1111-4111-8111-111111111111/77777777-7777-4777-8777-777777777777/no.webp')$q$),'past_due product upload denied');
select pg_temp.check((select count(*)=1 from businesses),'business onboarding remains readable');
reset role;
do $$declare state text;begin foreach state in array array['unpaid','paused','canceled','incomplete','incomplete_expired','inactive'] loop
 update subscriptions set status=state where business_id='11111111-1111-4111-8111-111111111111';
 perform pg_temp.check(not private.cx_premium_business('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),state||' denied');end loop;end$$;
update subscriptions set status='active',current_period_end=null where business_id='11111111-1111-4111-8111-111111111111';
select pg_temp.check(not private.cx_premium_business('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'null period denied');
update subscriptions set current_period_end=now()-interval '1 second' where business_id='11111111-1111-4111-8111-111111111111';
select pg_temp.check(not private.cx_premium_business('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'expired denied');
update subscriptions set status='trialing',trial_ends_at=now()+interval '1 day',current_period_end=now()+interval '1 day' where business_id='11111111-1111-4111-8111-111111111111';
select pg_temp.check(private.cx_premium_business('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'valid trial allowed');
update subscriptions set stripe_livemode=true where business_id='11111111-1111-4111-8111-111111111111';
select pg_temp.check(not private.cx_premium_business('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'other Stripe mode denied');
select pg_temp.check((select count(*)>0 from private.cx_billing_history),'changed binding preserves history');
rollback;
